      'dcim.dec.review.title': '{n} devices whose type and placement need confirming',
      'dcim.dec.review.titleOne': 'One device whose type and placement need confirming',
      'dcim.dec.review.why': 'The NetBox role does not match a known InfraNet type: the one proposed is inferred. Until you confirm (or tick "import anyway" at the bottom) the project is not created.',
