      'cbl.medium-cat.fiberOnCopper.t': 'Fibre category on a copper medium',
      'cbl.medium-cat.fiberOnCopper.w': '{cat} is an optical fibre, but the Medium is set to Copper. Set Medium = Fibre, or pick a Cat (copper) category.',
      'cbl.medium-cat.copperOnFiber.t': 'Copper category on a fibre medium',
      'cbl.medium-cat.copperOnFiber.w': '{cat} is a copper category, but the Medium is Fibre. Use an optical category (OS2/OM3/OM4/OM5) or change the Medium.',
      'cbl.medium-conn.fiberConnOnCopper.t': 'Optical connector on copper',
      'cbl.medium-conn.fiberConnOnCopper.w': '{conn} is an optical-fibre connector; copper terminates in RJ45. Check the Medium or the Connector.',
      'cbl.medium-conn.rj45OnFiber.t': 'RJ45 on fibre',
      'cbl.medium-conn.rj45OnFiber.w': 'An RJ45 connector terminates copper, not an optical fibre. Fibre uses LC, SC or MPO/MTP.',
      'cbl.speed-cat.t': 'Speed beyond the cable category',
      'cbl.speed-cat.w': '{speed} on {cat}: the category guarantees up to {catMax} at {catReach}m.',
      'cbl.speed-cat.rec': 'For {speed} at {recReach}m you need {rec}.',
      'cbl.speed-cat.recCat6': 'For {speed} at {recReach}m you need {rec} (on Cat6, 10G only holds up to ~55m).',
      'cbl.speed-cat.noCopper': 'This speed is not supported over copper: use fibre or DAC.',
      'cbl.copper-length.t': 'Copper run beyond 100m',
      'cbl.copper-length.w': '{len}m: TIA-568 limits a copper channel to 100m (90m permanent + 10m patch cords). Beyond that the link may fail to negotiate or stay unstable — use fibre or an intermediate device.',
      'cbl.cat-reach.t': '{cat} beyond {max}m',
      'cbl.cat-reach.w': '{len}m on {cat}: this category is specified only for channels up to {max}m (25/40GBASE-T). Beyond that the class is not guaranteed — for long runs use Cat6A at 100m or move to fibre.',
      'cbl.fiber-reach.t': '{cat} beyond {max}m at {speed}',
      'cbl.fiber-reach.w': '{len}m on {cat} at {speed}: the reach of this optical class at this speed is {max}m. Note: on multimode the distance DROPS as the bitrate rises (OM3 carries 300m at 10G but only 100m at 40G).',
      'cbl.dac-length.t': 'DAC too long',
      'cbl.dac-length.w': '{len}m: DAC cables reach ~5–7m (passive) or ~10m (active). For longer distances use optical transceivers + fibre.',
      'cbl.poe-fiber.t': 'PoE over fibre',
      'cbl.poe-fiber.w': 'Power over Ethernet only travels on copper: a fibre carries no power. You need an injector or local power at the remote device.',
      'cbl.poe-cat.t': 'PoE++ (90W) on Cat5e',
      'cbl.poe-cat.w': '802.3bt uses all 4 pairs at high current: on Cat5e it works but heats up in dense bundles. For heat dissipation and margin, Cat6/6A is recommended.',
      'cbl.speed-vs-snmp.t': 'Real speed beyond the documented one',
      'cbl.speed-vs-snmp.w': 'The port negotiates {real} but the cable is documented as {doc}. Update the Maximum speed, or check that the cabling sustains the real speed.',
      'cbl.medium-vs-snmp.t': 'Medium differs from SNMP',
      'cbl.medium-vs-snmp.w': 'SNMP reports {snmpL} but the cable is documented as {docL}. Align the Medium field with reality.',
      'cbl.native-mismatch.t': 'Native VLAN does not match',
      'cbl.native-mismatch.w': 'The two trunk ends have different native VLANs ({a} vs {b}). On a real trunk this is an error: untagged traffic lands in different VLANs on each side. Align the PVID on both devices.',
      'cbl.medium.copper': 'Copper', 'cbl.medium.fiber': 'Fibre', 'cbl.medium.dac': 'DAC',
